1	const PROCESSING_FEE = 5;
2	
3	const BASE_PREMIUM_BY_ITEM_TYPE = {
4	  sword: 100,
5	  amulet: 60,
6	  staff: 80,
7	  potion: 40,
8	  rune: 25,
9	  moonstone: 25,
10	} as const satisfies Record<string, number>;
11	
12	type InsurableItemType = keyof typeof BASE_PREMIUM_BY_ITEM_TYPE;
13	
14	const INSURANCE_VALUE_BY_ITEM_TYPE = {
15	  sword: 1000,
16	  amulet: 600,
17	  staff: 800,
18	  potion: 400,
19	  rune: 250,
20	  moonstone: 250,
21	} as const satisfies Record<InsurableItemType, number>;
22	
23	const DEDUCTIBLE_PER_DAMAGE = 100;
24	
25	// Distinct from HIGH_ENCHANTMENT_THRESHOLD: that one raises the premium at
26	// level 5, this one halves the reimbursement at level 8.
27	const REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
28	
29	const REIMBURSEMENT_ENCHANTMENT_RATE = 0.5;
30	
31	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
32	
33	const BLOCK_SIZE = 3;
34	
35	const BLOCK_BASE_PREMIUM = 60;
36	
37	const CURSE_SURCHARGE_RATE = 0.5;
38	
39	const HIGH_ENCHANTMENT_THRESHOLD = 5;
40	
41	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
42	
43	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
44	
45	const LOYALTY_YEARS_THRESHOLD = 2;
46	
47	const LOYALTY_DISCOUNT_RATE = 0.2;
48	
49	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
50	
51	export type QuoteResult = { premium: number };
52	
53	export type ClaimResult = { payout: number; remainingCap: number };
54	
55	export type ScenarioResult = QuoteResult | ClaimResult;
56	
57	export type ScenarioOutcome = { results: ScenarioResult[] };
58	
59	type Item = {
60	  type: InsurableItemType;
61	  cursed?: boolean;
62	  enchantment?: number;
63	};
64	
65	type Customer = { yearsWithMHPCO: number };
66	
67	type QuoteStep = { op: "quote"; items: Item[] };
68	
69	type Damage = { itemType: string; amount: number };
70	
71	type ClaimStep = {
72	  op: "claim";
73	  policy: number;
74	  incident: { cause: string; damages: Damage[] };
75	};
76	
77	type Step = QuoteStep | ClaimStep;
78	
79	type Scenario = { customer: Customer; steps: Step[] };
80	
81	// Amounts are rounded in the MHPCO's favour: premiums (charged to the
82	// customer) round up.
83	const roundPremiumInMHPCOsFavour = (amount: number): number =>
84	  Math.ceil(amount);
85	
86	// ...and payouts (paid to the customer) round down.
87	const roundPayoutInMHPCOsFavour = (amount: number): number =>
88	  Math.floor(amount);
89	
90	const countByItemType = (items: Item[]): Map<InsurableItemType, number> => {
91	  const counts = new Map<InsurableItemType, number>();
92	
93	  for (const item of items) {
94	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
95	  }
96	
97	  return counts;
98	};
99	
100	// Exactly 3 alike components form a building block at a special base premium.
101	const basePremiumForAlikeItems = (
102	  type: InsurableItemType,
103	  count: number,
104	): number =>
105	  count === BLOCK_SIZE
106	    ? BLOCK_BASE_PREMIUM
107	    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];
108	
109	const basePremiumOf = (items: Item[]): number =>
110	  [...countByItemType(items)]
111	    .map(([type, count]) => basePremiumForAlikeItems(type, count))
112	    .reduce((total, premium) => total + premium, 0);
113	
114	const ownBasePremiumOf = (item: Item): number =>
115	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
116	
117	// Item-specific modifiers apply to the affected item's own base premium,
118	// not to the policy total.
119	type ItemModifier = { appliesTo: (item: Item) => boolean; rate: number };
120	
121	const CURSE_MODIFIER: ItemModifier = {
122	  appliesTo: (item) => item.cursed === true,
123	  rate: CURSE_SURCHARGE_RATE,
124	};
125	
126	const HIGH_ENCHANTMENT_MODIFIER: ItemModifier = {
127	  appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
128	  rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
129	};
130	
131	const ITEM_MODIFIERS: ItemModifier[] = [
132	  CURSE_MODIFIER,
133	  HIGH_ENCHANTMENT_MODIFIER,
134	];
135	
136	const itemSurchargeOf = (items: Item[], modifier: ItemModifier): number =>
137	  items
138	    .filter(modifier.appliesTo)
139	    .reduce((total, item) => total + ownBasePremiumOf(item) * modifier.rate, 0);
140	
141	// Item modifiers accumulate: an item matching several of them pays each
142	// surcharge on its own base premium.
143	const itemSurchargesOf = (items: Item[]): number =>
144	  ITEM_MODIFIERS.reduce(
145	    (total, modifier) => total + itemSurchargeOf(items, modifier),
146	    0,
147	  );
148	
149	// Policy-wide modifiers are computed from the policy base premium, so the
150	// first insurance surcharge is 10 % of the base — not of base plus curse.
151	// A modifier's rate is signed: surcharges are positive, discounts negative.
152	type PolicyContext = { customer: Customer; precedingQuotes: number };
153	
154	type PolicyModifier = {
155	  appliesTo: (context: PolicyContext) => boolean;
156	  rate: number;
157	};
158	
159	const FIRST_INSURANCE_MODIFIER: PolicyModifier = {
160	  appliesTo: () => true,
161	  rate: FIRST_INSURANCE_SURCHARGE_RATE,
162	};
163	
164	const LOYALTY_MODIFIER: PolicyModifier = {
165	  appliesTo: ({ customer }) =>
166	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
167	  rate: -LOYALTY_DISCOUNT_RATE,
168	};
169	
170	// Each item in a quote counts as a first insurance regardless of customer
171	// history, so this discount stacks with the first insurance surcharge.
172	const FOLLOW_UP_CONTRACT_MODIFIER: PolicyModifier = {
173	  appliesTo: ({ precedingQuotes }) => precedingQuotes >= 1,
174	  rate: -FOLLOW_UP_CONTRACT_DISCOUNT_RATE,
175	};
176	
177	const POLICY_MODIFIERS: PolicyModifier[] = [
178	  FIRST_INSURANCE_MODIFIER,
179	  LOYALTY_MODIFIER,
180	  FOLLOW_UP_CONTRACT_MODIFIER,
181	];
182	
183	// Policy modifiers accumulate: each applicable one is computed on the same
184	// policy base premium, never compounded on top of another.
185	const policyAdjustmentOf = (
186	  basePremium: number,
187	  context: PolicyContext,
188	): number =>
189	  POLICY_MODIFIERS.filter((modifier) => modifier.appliesTo(context)).reduce(
190	    (total, modifier) => total + basePremium * modifier.rate,
191	    0,
192	  );
193	
194	const quotePremium = (items: Item[], context: PolicyContext): number => {
195	  const basePremium = basePremiumOf(items);
196	
197	  return roundPremiumInMHPCOsFavour(
198	    basePremium +
199	      itemSurchargesOf(items) +
200	      policyAdjustmentOf(basePremium, context) +
201	      PROCESSING_FEE,
202	  );
203	};
204	
205	const insuranceSumOf = (items: Item[]): number =>
206	  items.reduce(
207	    (total, item) => total + INSURANCE_VALUE_BY_ITEM_TYPE[item.type],
208	    0,
209	  );
210	
211	// A reimbursement clause reduces the damage amount to a fraction of itself,
212	// keyed on the insured item's attributes — which the damage entry does not
213	// carry, it names only the item type. Same {appliesTo, rate} shape as
214	// ItemModifier, but the rate is a share of the damage rather than a surcharge
215	// on a base premium. Only one clause exists so far, so the selection below is
216	// a plain conditional; a second clause will need a rule for which one wins.
217	type ReimbursementClause = { appliesTo: (item: Item) => boolean; rate: number };
218	
219	const HIGH_ENCHANTMENT_CLAUSE: ReimbursementClause = {
220	  appliesTo: (item) =>
221	    (item.enchantment ?? 0) >= REIMBURSEMENT_ENCHANTMENT_THRESHOLD,
222	  rate: REIMBURSEMENT_ENCHANTMENT_RATE,
223	};
224	
225	const FULL_REIMBURSEMENT_RATE = 1;
226	
227	const reimbursementRateFor = (insuredItem: Item): number =>
228	  HIGH_ENCHANTMENT_CLAUSE.appliesTo(insuredItem)
229	    ? HIGH_ENCHANTMENT_CLAUSE.rate
230	    : FULL_REIMBURSEMENT_RATE;
231	
232	const reimbursementFor = (damageAmount: number, insuredItem: Item): number =>
233	  damageAmount * reimbursementRateFor(insuredItem);
234	
235	// Each damage entry is a distinct damaged item, so it claims one insured item
236	// of that type and no other entry may claim the same one.
237	const claimInsuredItem = (
238	  damage: Damage,
239	  unclaimedItems: Item[],
240	): { insuredItem: Item; remainingItems: Item[] } => {
241	  const index = unclaimedItems.findIndex(
242	    (item) => item.type === damage.itemType,
243	  );
244	
245	  if (index === -1) {
246	    throw new Error(
247	      `the policy does not cover a damaged ${damage.itemType}`,
248	    );
249	  }
250	
251	  return {
252	    insuredItem: unclaimedItems[index],
253	    remainingItems: unclaimedItems.filter((_, at) => at !== index),
254	  };
255	};
256	
257	// Rejecting a damage entry is kept apart from pricing it, so payoutForDamage
258	// below is purely a calculation and its name stays true. Zero is a valid
259	// amount: the spec rejects only negative ones.
260	//
261	// All four throw sites (this one, rejectInvalidDamage, claimInsuredItem and
262	// policyCreatedBy) raise a plain Error. A named error type has been
263	// reconsidered at each and deferred again: no consumer discriminates between
264	// them — every test asserts a bare .toThrow() or matches the message text, and
265	// all four mean the same thing, "the submitted scenario is invalid". The CLI is
266	// the first real consumer; introduce a type when a CLI test demands different
267	// handling per cause, not merely a non-zero exit.
268	// The MHPCO insures only the item types on its price list.
269	const rejectUninsurableItem = (item: Item): void => {
270	  if (!(item.type in BASE_PREMIUM_BY_ITEM_TYPE)) {
271	    throw new Error(`the MHPCO does not insure a ${item.type}`);
272	  }
273	};
274	
275	const rejectInvalidDamage = (damage: Damage): void => {
276	  if (damage.amount < 0) {
277	    throw new Error(
278	      `the damage to the ${damage.itemType} is a negative amount`,
279	    );
280	  }
281	};
282	
283	// A deductible applies per damage event, i.e. once per damaged item.
284	const payoutForDamage = (damage: Damage, insuredItem: Item): number =>
285	  reimbursementFor(damage.amount, insuredItem) - DEDUCTIBLE_PER_DAMAGE;
286	
287	// Each damage entry carries its own deductible, so this is a plain sum over
288	// the entries. The policy's cap is applied by the caller.
289	const desiredPayoutForIncident = (
290	  damages: Damage[],
291	  insuredItems: Item[],
292	): number =>
293	  damages.reduce(
294	    ({ total, unclaimedItems }, damage) => {
295	      rejectInvalidDamage(damage);
296	
297	      const { insuredItem, remainingItems } = claimInsuredItem(
298	        damage,
299	        unclaimedItems,
300	      );
301	
302	      return {
303	        total: total + payoutForDamage(damage, insuredItem),
304	        unclaimedItems: remainingItems,
305	      };
306	    },
307	    { total: 0, unclaimedItems: insuredItems },
308	  ).total;
309	
310	// A policy is created by a quote step; claims draw down its remaining cap.
311	// The insured items are retained because payout clauses depend on them.
312	type Policy = { remainingCap: number; items: Item[] };
313	
314	const capFor = (items: Item[]): number =>
315	  insuranceSumOf(items) * CAP_MULTIPLE_OF_INSURANCE_SUM;
316	
317	// A claim quotes its policy by the index of the step that created it, so
318	// policies are keyed by that index rather than collected in a list.
319	type ScenarioState = {
320	  customer: Customer;
321	  policiesByStep: Map<number, Policy>;
322	  precedingQuotes: number;
323	  results: ScenarioResult[];
324	};
325	
326	const initialState = (customer: Customer): ScenarioState => ({
327	  customer,
328	  policiesByStep: new Map(),
329	  precedingQuotes: 0,
330	  results: [],
331	});
332	
333	// Each step handler folds the state forward: it reads what earlier steps
334	// established and returns the state the following steps will see.
335	const applyQuote = (
336	  state: ScenarioState,
337	  step: QuoteStep,
338	  stepIndex: number,
339	): ScenarioState => {
340	  const { customer, precedingQuotes } = state;
341	
342	  step.items.forEach(rejectUninsurableItem);
343	
344	  const premium = quotePremium(step.items, { customer, precedingQuotes });
345	
346	  return {
347	    ...state,
348	    policiesByStep: new Map(state.policiesByStep).set(stepIndex, {
349	      remainingCap: capFor(step.items),
350	      items: step.items,
351	    }),
352	    precedingQuotes: precedingQuotes + 1,
353	    results: [...state.results, { premium }],
354	  };
355	};
356	
357	// A resolving guard rather than a void `reject*` one: the other validators
358	// check a value the caller already holds, this one produces the value. Hence
359	// the noun name — it reads as a lookup that refuses to fail silently.
360	const policyCreatedBy = (
361	  stepIndex: number,
362	  policiesByStep: Map<number, Policy>,
363	): Policy => {
364	  const policy = policiesByStep.get(stepIndex);
365	
366	  if (policy === undefined) {
367	    throw new Error(`no policy was created by step ${stepIndex}`);
368	  }
369	
370	  return policy;
371	};
372	
373	const applyClaim = (state: ScenarioState, step: ClaimStep): ScenarioState => {
374	  const policy = policyCreatedBy(step.policy, state.policiesByStep);
375	
376	  const desiredPayout = desiredPayoutForIncident(
377	    step.incident.damages,
378	    policy.items,
379	  );
380	  // The total payout per policy is capped, so a claim can pay out no more
381	  // than the cap the policy has left.
382	  const payout = roundPayoutInMHPCOsFavour(
383	    Math.min(desiredPayout, policy.remainingCap),
384	  );
385	  const remainingCap = policy.remainingCap - payout;
386	
387	  return {
388	    ...state,
389	    policiesByStep: new Map(state.policiesByStep).set(step.policy, {
390	      ...policy,
391	      remainingCap,
392	    }),
393	    results: [...state.results, { payout, remainingCap }],
394	  };
395	};
396	
397	const applyStep = (
398	  state: ScenarioState,
399	  step: Step,
400	  stepIndex: number,
401	): ScenarioState =>
402	  step.op === "quote"
403	    ? applyQuote(state, step, stepIndex)
404	    : applyClaim(state, step);
405	
406	export const runScenario = (scenario: unknown): ScenarioOutcome => {
407	  const { customer, steps } = scenario as Scenario;
408	
409	  const { results } = steps.reduce(applyStep, initialState(customer));
410	
411	  return { results };
412	};
